const state = { user: { name: "Hariom", scores: [10, 20, 30] } }
const newState = {
  ...state,
  user: {
    ...state.user,
    name: "Amit",
    scores: [...state.user.scores, 40]
  }
}
return {
  original: state,
  updated: newState
}
